{"command":"create","file_text":"package main

import (
	"context"
	"crypto/rand"
	"crypto/subtle"
	"encoding/hex"
	"errors"
	"fmt"
	"log"
	"sync"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
	"go.mongodb.org/mongo-driver/mongo"
	"go.mongodb.org/mongo-driver/mongo/options"
)

type App struct {
	cfg    Config
	pg     *pgxpool.Pool
	mongo  *mongo.Client
	mdb    *mongo.Database
	rtMu   sync.Mutex
}

func NewApp(ctx context.Context, cfg Config) (*App, error) {
	pool, err := pgxpool.New(ctx, cfg.PostgresURL)
	if err != nil {
		return nil, fmt.Errorf("pg connect: %w", err)
	}
	if err := pool.Ping(ctx); err != nil {
		return nil, fmt.Errorf("pg ping: %w", err)
	}
	mclient, err := mongo.Connect(ctx, options.Client().ApplyURI(cfg.MongoURI))
	if err != nil {
		return nil, fmt.Errorf("mongo connect: %w", err)
	}
	if err := mclient.Ping(ctx, nil); err != nil {
		return nil, fmt.Errorf("mongo ping: %w", err)
	}
	a := &App{
		cfg:   cfg,
		pg:    pool,
		mongo: mclient,
		mdb:   mclient.Database("arena"),
	}
	if err := a.Migrate(ctx); err != nil {
		return nil, fmt.Errorf("migrate: %w", err)
	}
	if err := a.MaterializeMongo(ctx); err != nil {
		return nil, fmt.Errorf("materialize mongo: %w", err)
	}
	if err := a.SeedDefaults(ctx); err != nil {
		return nil, fmt.Errorf("seed: %w", err)
	}
	return a, nil
}

func (a *App) Close() {
	if a.pg != nil {
		a.pg.Close()
	}
	if a.mongo != nil {
		_ = a.mongo.Disconnect(context.Background())
	}
}

// tx runs fn inside a serializable transaction with retry on snapshot conflict.
func (a *App) tx(ctx context.Context, fn func(pgx.Tx) error) error {
	for i := 0; i < 4; i++ {
		err := func() error {
			t, err := a.pg.BeginTx(ctx, pgx.TxOptions{IsoLevel: pgx.Serializable})
			if err != nil {
				return err
			}
			defer t.Rollback(ctx)
			if err := fn(t); err != nil {
				return err
			}
			return t.Commit(ctx)
		}()
		if err == nil {
			return nil
		}
		if isSnapshotConflict(err) {
			time.Sleep(time.Duration(20<<(i)) * time.Millisecond)
			continue
		}
		return err
	}
	return errors.New("concurrent_conflict")
}

func isSnapshotConflict(err error) bool {
	s := err.Error()
	return contains(s, "could not serialize access") || contains(s, "40P01") || contains(s, "40001") || contains(s, "concurrent_conflict")
}

func contains(s, sub string) bool {
	return len(sub) == 0 || (len(s) >= len(sub) && (func() bool {
		for i := 0; i+len(sub) <= len(s); i++ {
			if s[i:i+len(sub)] == sub {
				return true
			}
		}
		return false
	})())
}

func newToken() string {
	b := make([]byte, 24)
	rand.Read(b)
	return hex.EncodeToString(b)
}

func newUUID() string {
	return uuidStr()
}

func uuidStr() string {
	b := make([]byte, 16)
	rand.Read(b)
	b[6] = (b[6] & 0x0f) | 0x40
	b[8] = (b[8] & 0x3f) | 0x80
	return fmt.Sprintf("%x-%x-%x-%x-%x", b[0:4], b[4:6], b[6:8], b[8:10], b[10:16])
}

func secureEq(a, b string) bool {
	return subtle.ConstantTimeCompare([]byte(a), []byte(b)) == 1
}

func ptr[T any](v T) *T { return &v }

func nowRFC() string { return time.Now().UTC().Format(time.RFC3339Nano) }

var _ = log.Printf","path":"/workspace/backend/app.go"}

{"command":"create","file_text":"package main

import (
	"context"

	"go.mongodb.org/mongo-driver/bson"
	"go.mongodb.org/mongo-driver/mongo/options"
)

// MaterializeMongo creates collections and indexes so reset materializes structure.
func (a *App) MaterializeMongo(ctx context.Context) error {
	db := a.mdb
	colls := []string{"audit_events", "realtime_events", "audit_requests"}
	for _, c := range colls {
		if err := db.CreateCollection(ctx, c); err != nil {
			// ignore already exists
			if !isMongoAlreadyExists(err) {
				return err
			}
		}
	}
	indexes := map[string][]mongoIndex{
		"audit_events": {
			{Keys: bson.D{{Key: "timestamp", Value: 1}}},
			{Keys: bson.D{{Key: "entity_type", Value: 1}, {Key: "entity_id", Value: 1}}},
			{Keys: bson.D{{Key: "user_id", Value: 1}, {Key: "timestamp", Value: -1}}},
			{Keys: bson.D{{Key: "action", Value: 1}}},
		},
		"realtime_events": {
			{Keys: bson.D{{Key: "seq", Value: 1}}, Unique: true},
			{Keys: bson.D{{Key: "timestamp", Value: 1}}},
			{Keys: bson.D{{Key: "entity_type", Value: 1}, {Key: "timestamp", Value: -1}}},
		},
		"audit_requests": {
			{Keys: bson.D{{Key: "request_id", Value: 1}}},
		},
	}
	for coll, idxs := range indexes {
		c := db.Collection(coll)
		for _, ix := range idxs {
			opts := options.Index()
			if ix.Unique {
				opts.SetUnique(true)
			}
			_, err := c.Indexes().CreateOne(ctx, ix, opts)
			if err != nil && !isMongoAlreadyExists(err) {
				return err
			}
		}
	}
	return nil
}

type mongoIndex struct {
	Keys   any
	Unique bool
}

func isMongoAlreadyExists(err error) bool {
	s := err.Error()
	return contains(s, "already exists") || contains(s, "NamespaceExists")
}

func (a *App) ResetMongo(ctx context.Context) error {
	colls := []string{"audit_events", "realtime_events", "audit_requests"}
	for _, c := range colls {
		_ = a.mdb.Collection(c).Drop(ctx)
	}
	return a.MaterializeMongo(ctx)
}","path":"/workspace/backend/mongo.go"}

{"command":"create","file_text":"package main

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
)

func hashPassword(password, salt string) string {
	h := sha256.New()
	h.Write([]byte(salt))
	h.Write([]byte(password))
	h.Write([]byte("labpd-v1"))
	return hex.EncodeToString(h.Sum(nil))
}

func newSalt() string {
	return newToken()[:16]
}

// SeedDefaults seeds the four default sample types if missing.
func (a *App) SeedDefaults(ctx context.Context) error {
	defaults := []struct {
		name         string
		container    string
		tmin, tmax   float64
		qual         string
		cooled       bool
		batching     bool
		incompatible []string
	}{
		{"Amber", "standard", 15, 25, "", false, true, nil},
		{"Indigo", "standard", 15, 25, "", false, true, []string{"Amber"}},
		{"Frost", "cooled", 2, 8, "", true, true, nil},
		{"Pulse", "standard", 15, 25, "", false, false, nil},
	}
	for _, d := range defaults {
		var exists bool
		err := a.pg.QueryRow(ctx, `SELECT EXISTS(SELECT 1 FROM sample_types WHERE name=$1)`, d.name).Scan(&exists)
		if err != nil {
			return err
		}
		if exists {
			continue
		}
		_, err = a.pg.Exec(ctx, `INSERT INTO sample_types
			(sample_type_id, name, qualified_collector_required, required_qualification, container_type, temperature_min_c, temperature_max_c, requires_cooled_route, batching_allowed, incompatible, is_default)
			VALUES ($1,$2,true,$3,$4,$5,$6,$7,$8,$9,true)`,
			uuidStr(), d.name, d.name, d.container, d.tmin, d.tmax, d.cooled, d.batching, d.incompatible)
		if err != nil {
			return err
		}
	}
	return nil
}

// EnsureInitialAdmin creates the first administrator account when no users exist.
func (a *App) EnsureInitialAdmin(ctx context.Context) error {
	var count int
	if err := a.pg.QueryRow(ctx, `SELECT COUNT(*) FROM users`).Scan(&count); err != nil {
		return err
	}
	if count > 0 {
		return nil
	}
	if a.cfg.AdminUser == "" || a.cfg.AdminPass == "" {
		return fmt.Errorf("ADMIN_USERNAME/ADMIN_PASSWORD not set and no users exist")
	}
	salt := newSalt()
	_, err := a.pg.Exec(ctx, `INSERT INTO users
		(user_id, username, password_hash, password_salt, roles, qualifications, active, full_name)
		VALUES ($1,$2,$3,$4,$5,$6,true,'System Administrator')`,
		uuidStr(), a.cfg.AdminUser, hashPassword(a.cfg.AdminPass, salt), salt,
		[]string{"administrator"}, []string{})
	return err
}","path":"/workspace/backend/seed.go"}

