{"command":"create","file_text":"package main

import (
	"context"
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"strings"
	"time"

	"github.com/jackc/pgx/v5"
)

// ctxKey types
type ctxKey int

const (
	ckUser ctxKey = iota
)

// AuthUser holds the authenticated user context.
type AuthUser struct {
	UserID           string
	Username         string
	FullName         string
	Roles            []string
	ActiveRole       string
	Qualifications   []string
	AssignedLocation *string
}

func (u *AuthUser) hasRole(r string) bool {
	for _, x := range u.Roles {
		if x == r {
			return true
		}
	}
	return false
}

// apiError carries an HTTP status and a contract code.
type apiError struct {
	status int
	code   string
	msg    string
}

func (e *apiError) Error() string { return e.msg }

func errCode(status int, code, msg string) *apiError {
	if msg == "" {
		msg = code
	}
	return &apiError{status: status, code: code, msg: msg}
}

var (
	errUnauthorized = errCode(401, "unauthorized", "authentication required")
	errForbidden    = errCode(403, "forbidden", "forbidden")
	errNotFound     = errCode(404, "not_found", "not found")
	errRoleNotSel   = errCode(409, "role_not_selected", "active role not selected")
	errInvalidJSON  = errCode(400, "invalid_json", "invalid json body")
	errInternal     = errCode(500, "internal_error", "internal error")
	errSnapshot     = errCode(409, "state_snapshot_changed", "state snapshot changed")
	errConflict     = errCode(409, "concurrent_conflict", "concurrent conflict")
)

func writeData(w http.ResponseWriter, status int, data any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(map[string]any{"data": data})
}

func writeError(w http.ResponseWriter, e *apiError) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(e.status)
	_ = json.NewEncoder(w).Encode(map[string]any{"error": e.msg, "code": e.code})
}

// decodeJSON decodes a strict JSON body (no extra fields enforced loosely here).
func decodeJSON(r *http.Request, dst any) error {
	if r.Body == nil {
		return errors.New("empty body")
	}
	body, err := io.ReadAll(r.Body)
	if err != nil {
		return err
	}
	if len(strings.TrimSpace(string(body))) == 0 {
		return errors.New("empty body")
	}
	dec := json.NewDecoder(strings.NewReader(string(body)))
	dec.DisallowUnknownFields()
	if err := dec.Decode(dst); err != nil {
		return err
	}
	return nil
}

// authMiddleware extracts the bearer [REDACTED] and loads the user.
func (a *App) authMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		token := bearerToken(r)
		if token == "" {
			writeError(w, errUnauthorized)
			return
		}
		u, err := a.loadUserByToken(r.Context(), token)
		if err != nil {
			writeError(w, errUnauthorized)
			return
		}
		ctx := context.WithValue(r.Context(), ckUser, u)
		next.ServeHTTP(w, r.WithContext(ctx))
	})
}

func currentUser(r *http.Request) *AuthUser {
	if u, ok := r.Context().Value(ckUser).(*AuthUser); ok {
		return u
	}
	return nil
}

func bearerToken(r *http.Request) string {
	h := r.Header.Get("Authorization")
	if strings.HasPrefix(h, "Bearer ") {
		return strings.TrimPrefix(h, "Bearer ")
	}
	if c, err := r.Cookie("session"); err == nil && c.Value != "" {
		return c.Value
	}
	return ""
}

// requireRole returns an apiError if the active role is not in allowed.
// allowedRoles is the set of roles permitted for the operation.
func requireRole(u *AuthUser, allowed ...string) *apiError {
	if u.ActiveRole == "" {
		return errRoleNotSel
	}
	ok := false
	for _, r := range allowed {
		if u.ActiveRole == r {
			ok = true
			break
		}
	}
	if !ok {
		return errForbidden
	}
	// active role must be one of the user's roles
	if !u.hasRole(u.ActiveRole) {
		return errForbidden
	}
	return nil
}

// loadUserByToken loads user + active role from session.
func (a *App) loadUserByToken(ctx context.Context, token string) (*AuthUser, error) {
	var (
		userID, username, fullName string
		roles, quals                []string
		activeRole                 string
		assignedLoc                 *string
	)
	err := a.pg.QueryRow(ctx, `
		SELECT u.user_id, u.username, u.full_name, u.roles, u.qualifications, s.active_role, u.assigned_location_id::text
		FROM sessions s JOIN users u ON u.user_id = s.user_id
		WHERE s.token = $1 AND u.active = true`, token).
		Scan(&userID, &username, &fullName, &roles, &quals, &activeRole, &assignedLoc)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, errors.New("no session")
		}
		return nil, err
	}
	return &AuthUser{
		UserID:           userID,
		Username:         username,
		FullName:         fullName,
		Roles:            roles,
		ActiveRole:       activeRole,
		Qualifications:   quals,
		AssignedLocation: assignedLoc,
	}, nil
}

// parseTime parses an RFC3339 timestamp, returning an apiError on failure.
func parseTime(s string, code string) (time.Time, *apiError) {
	if s == "" {
		return time.Time{}, errCode(400, code, "missing time")
	}
	t, err := time.Parse(time.RFC3339Nano, s)
	if err != nil {
		t, err = time.Parse(time.RFC3339, s)
		if err != nil {
			return time.Time{}, errCode(400, code, "invalid time")
		}
	}
	return t.UTC(), nil
}

func rfc(t time.Time) string {
	if t.IsZero() {
		return ""
	}
	return t.UTC().Format(time.RFC3339Nano)
}

func parseUUID(s string) (string, bool) {
	if len(s) != 36 {
		return "", false
	}
	// basic shape check
	for i, c := range s {
		switch i {
		case 8, 13, 18, 23:
			if c != '-' {
				return "", false
			}
		default:
			if !((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')) {
				return "", false
			}
		}
	}
	return strings.ToLower(s), true
}

// withIdempotency wraps a handler that needs idempotency_key, returning stored response on repeat.
func (a *App) withIdempotency(r *http.Request, op, key string, fn func() (any, int, *apiError)) (any, int, *apiError) {
	if key == "" {
		return nil, 400, errCode(400, "idempotency_required", "idempotencyKey required")
	}
	// check existing
	var respBytes []byte
	var sc int
	err := a.pg.QueryRow(r.Context(), `SELECT response, status_code FROM idempotency_keys WHERE key=$1 AND operation=$2`, key, op).Scan(&respBytes, &sc)
	if err == nil {
		// replay
		var data any
		_ = json.Unmarshal(respBytes, &data)
		return data, sc, nil
	}
	data, status, e := fn()
	if e != nil {
		return nil, e.status, e
	}
	b, _ := json.Marshal(data)
	_, _ = a.pg.Exec(r.Context(), `INSERT INTO idempotency_keys (key, operation, response, status_code) VALUES ($1,$2,$3,$4) ON CONFLICT DO NOTHING`, key, op, b, status)
	return data, status, nil
}","path":"/workspace/backend/http.go"}

{"command":"create","file_text":"package main

import (
	"context"
	"time"

	"go.mongodb.org/mongo-driver/bson"
	"go.mongodb.org/mongo-driver/mongo/options"
)

type auditRecord struct {
	ActorID    string
	Role       string
	Action     string
	EntityType string
	EntityID   string
	Success    bool
	OccurredAt time.Time
	Details    map[string]any
}

func (a *App) audit(ctx context.Context, u *AuthUser, action, entityType, entityID string, success bool, details map[string]any) {
	if u == nil {
		u = &AuthUser{}
	}
	rec := bson.M{
		"auditId":     uuidStr(),
		"actorId":     u.UserID,
		"role":        u.ActiveRole,
		"actorRole":   u.ActiveRole,
		"action":      action,
		"entityType":  entityType,
		"entityType":  entityType,
		"entityId":    entityID,
		"success":     success,
		"occurredAt":  time.Now().UTC(),
		"timestamp":   time.Now().UTC(),
		"details":     details,
	}
	_, _ = a.mdb.Collection("audit_events").InsertOne(ctx, rec)
}

// realtime event seq counter
func (a *App) emitRealtime(ctx context.Context, etype, entityType, entityID string, payload map[string]any) {
	seq := a.nextSeq(ctx)
	_, _ = a.mdb.Collection("realtime_events").InsertOne(ctx, bson.M{
		"id":          seq,
		"seq":         seq,
		"type":        etype,
		"entityType":  entityType,
		"entityId":    entityID,
		"payload":     payload,
		"createdAt":   time.Now().UTC(),
		"timestamp":   time.Now().UTC(),
	})
}

func (a *App) nextSeq(ctx context.Context) int64 {
	for {
		var seq int64
		err := a.pg.QueryRow(ctx, `SELECT seq FROM network_revision WHERE id=1 FOR UPDATE`).Scan(&seq)
		if err != nil {
			return time.Now().UnixNano()
		}
		seq++
		_, err = a.pg.Exec(ctx, `UPDATE network_revision SET seq=$1 WHERE id=1`, seq)
		if err == nil {
			return seq
		}
	}
}

func init() {
	// network_revision table is created in migrate; add seq column if missing at runtime via migration
}

func (a *App) ensureSeqCol(ctx context.Context) {
	_, _ = a.pg.Exec(ctx, `ALTER TABLE network_revision ADD COLUMN IF NOT EXISTS seq bigint NOT NULL DEFAULT 0`)
	_, _ = a.pg.Exec(ctx, `UPDATE network_revision SET seq=0 WHERE id=1 AND seq IS NULL`)
}

func realtimeQuery(ctx context.Context, a *App, since int64, limit int) ([]bson.M, int64, error) {
	if limit <= 0 {
		limit = 500
	}
	opts := options.Find().SetSort(bson.D{{Key: "seq", Value: 1}}).SetLimit(int64(limit))
	filter := bson.M{}
	if since > 0 {
		filter["seq"] = bson.M{"$gt": since}
	}
	cur, err := a.mdb.Collection("realtime_events").Find(ctx, filter, opts)
	if err != nil {
		return nil, 0, err
	}
	defer cur.Close(ctx)
	var out []bson.M
	if err := cur.All(ctx, &out); err != nil {
		return nil, 0, err
	}
	var last int64 = since
	for _, d := range out {
		if s, ok := d["seq"].(int64); ok && s > last {
			last = s
		}
	}
	return out, last, nil
}

func auditSearch(ctx context.Context, a *App, q auditQuery) (auditSearchResult, error) {
	filter := bson.M{}
	if q.ActorID != "" {
		filter["actorId"] = q.ActorID
	}
	if q.EntityType != "" {
		filter["entityType"] = q.EntityType
	}
	if q.EntityID != "" {
		filter["entityId"] = q.EntityID
	}
	if q.Action != "" {
		filter["action"] = q.Action
	}
	if q.Role != "" {
		filter["role"] = q.Role
	}
	if q.Success != nil {
		filter["success"] = *q.Success
	}
	if !q.FromTime.IsZero() || !q.ToTime.IsZero() {
		tf := bson.M{}
		if !q.FromTime.IsZero() {
			tf["$gte"] = q.FromTime
		}
		if !q.ToTime.IsZero() {
			tf["$lte"] = q.ToTime
		}
		filter["occurredAt"] = tf
	}
	if q.Query != "" {
		filter["$or"] = bson.A{
			bson.M{"action": bson.M{"$regex": q.Query, "$options": "i"}},
			bson.M{"entityType": bson.M{"$regex": q.Query, "$options": "i"}},
			bson.M{"entityId": bson.M{"$regex": q.Query, "$options": "i"}},
		}
	}
	total, err := a.mdb.Collection("audit_events").CountDocuments(ctx, filter)
	if err != nil {
		return auditSearchResult{}, err
	}
	order := 1
	if q.Order == "newest_first" {
		order = -1
	}
	opts := options.Find().SetSort(bson.D{{Key: "occurredAt", Value: order}, {Key: "_id", Value: order}}).
		SetSkip(int64(q.Offset)).SetLimit(int64(q.Limit))
	cur, err := a.mdb.Collection("audit_events").Find(ctx, filter, opts)
	if err != nil {
		return auditSearchResult{}, err
	}
	defer cur.Close(ctx)
	var out []bson.M
	if err := cur.All(ctx, &out); err != nil {
		return auditSearchResult{}, err
	}
	entries := make([]map[string]any, 0, len(out))
	for _, d := range out {
		entries = append(entries, normalizeAudit(d))
	}
	hasMore := q.Offset+len(entries) < int(total)
	res := auditSearchResult{
		Entries: entries,
		Total:   int(total),
		Returned: len(entries),
		Offset:  q.Offset,
		Limit:   q.Limit,
		Order:   q.Order,
		HasMore: hasMore,
	}
	if q.Offset+len(entries) < int(total) {
		no := q.Offset + len(entries)
		res.NextOffset = &no
	}
	return res, nil
}

func normalizeAudit(d bson.M) map[string]any {
	oid := getStr(d, "_id")
	aid := getStr(d, "auditId")
	if aid == "" {
		aid = oid
	}
	return map[string]any{
		"auditId":    aid,
		"audit_id":   aid,
		"actorId":    getStr(d, "actorId"),
		"actor_id":   getStr(d, "actorId"),
		"role":        getStr(d, "role"),
		"actorRole":   getStr(d, "role"),
		"action":      getStr(d, "action"),
		"entityType": getStr(d, "entityType"),
		"entity_type": getStr(d, "entityType"),
		"entityId":   getStr(d, "entityId"),
		"entity_id":  getStr(d, "entityId"),
		"success":    getBool(d, "success"),
		"occurredAt": getTime(d, "occurredAt"),
		"occurred_at": getTime(d, "occurredAt"),
		"details":    d["details"],
	}
}

func getStr(d bson.M, k string) string {
	if v, ok := d[k]; ok {
		switch t := v.(type) {
		case string:
			return t
		}
	}
	return ""
}

func getBool(d bson.M, k string) bool {
	if v, ok := d[k]; ok {
		if b, ok := v.(bool); ok {
			return b
		}
	}
	return false
}

func getTime(d bson.M, k string) string {
	if v, ok := d[k]; ok {
		switch t := v.(type) {
		case time.Time:
			return t.UTC().Format(time.RFC3339Nano)
		case string:
			return t
		}
	}
	return ""
}

type auditQuery struct {
	Query     string
	ActorID   string
	EntityType string
	EntityID  string
	Action    string
	Role      string
	Success   *bool
	FromTime  time.Time
	ToTime    time.Time
	Limit     int
	Offset    int
	Order     string
}

type auditSearchResult struct {
	Entries    []map[string]any `json:"entries"`
	Total      int              `json:"total"`
	Returned   int              `json:"returned"`
	Offset     int              `json:"offset"`
	Limit      int              `json:"limit"`
	Order      string           `json:"order"`
	HasMore    bool             `json:"hasMore"`
	NextOffset *int             `json:"nextOffset,omitempty"`
}","path":"/workspace/backend/audit.go"}

