func (a *App) tx(ctx context.Context, fn func(pgxTx) error) error {
	for i := 0; i < 4; i++ {
		err := func() error {
			t, err := a.pg.BeginTx(ctx, pgx.TxOptions{IsoLevel: pgx.Serializable})
			if err != nil {
				return err
			}
			defer t.Rollback(ctx)
			if err := fn(t); err != nil {
				return err
			}
			return t.Commit(ctx)
		}()
		if err == nil {
			return nil
		}
		if isSnapshotConflict(err) {
			time.Sleep(time.Duration(20<<(i)) * time.Millisecond)
			continue
		}
		return err
	}
	return errors.New("concurrent_conflict")
