// pgxTx is the subset of pgx.Tx used by handlers and planning.
type pgxTx interface {
	Exec(ctx context.Context, sql string, args ...any) (pgx.CommandTag, error)
	Query(ctx context.Context, sql string, args ...any) (pgx.Rows, error)
	QueryRow(ctx context.Context, sql string, args ...any) pgx.Row
}

// buildJourneyTx adapts buildJourney to the pgxTx interface within a transaction.
func (a *App) buildJourneyTx(ctx context.Context, tx pgxTx, in serviceabilityInput, st *sampleTypeRow, entry *networkNode, route []routeStep, labID string, estArrival interface{}, alreadySealed bool, sampleID string) (*planJourneyResult, *apiError) {
	estT, _ := estArrival.(interface{ IsZero() bool })
	_ = estT
	// Re-use the standalone buildJourney logic by wrapping tx as pgxQuerier-compatible.
	return a.buildJourneyOn(ctx, tx, in, st, entry, route, labID, toTime(estArrival), alreadySealed, sampleID)
}

func toTime(v any) interface {
	IsZero() bool
	Add(d interface{}) interface{}
} {
	return nil
}

// writeAPIError writes an error returned from a tx-fn (which may be *apiError or a plain error).
func writeAPIError(w http.ResponseWriter, err error) {
	if e, ok := err.(*apiError); ok {
		writeError(w, e)
		return
	}
	writeError(w, errInternal)
