{"command":"str_replace","new_str":"// buildJourneyOn creates a journey with stops and assignments from a route. If alreadySealed,
// no collection assignment is created. tx must be the active transaction.
func (a *App) buildJourneyOn(ctx context.Context, tx pgxTx, in serviceabilityInput, st *sampleTypeRow, entry *networkNode, route []routeStep, labID string, estArrival time.Time, alreadySealed bool, sampleID string) (*planJourneyResult, *apiError) {
	journeyID := uuidStr()
	routeMode := "direct"
	if len(route) > 2 {
		routeMode = "multi_stop"
	}
	collectTime := in.EarliestCollect
	if collectTime.IsZero() {
		collectTime = in.RequestedAt
	}
	var totalCost float64
	for _, s := range route {
		totalCost += float64(s.TravelMin)
	}

	_, err := tx.Exec(ctx, `INSERT INTO journeys (journey_id, parent_journey_id, plan_version, route_mode, status, estimated_delivery_at, total_cost_units, valid, target_laboratory_id, already_sealed)
		VALUES ($1,NULL,1,$2,'planned',$3,$4,true,$5,$6)`,
