// handleRecordHandlingCheckpoint implements POST /api/record-handling-checkpoint.
func (a *App) handleRecordHandlingCheckpoint(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
		return
	}
	u := currentUser(r)
	if e := requireRole(u, workerRoles()...); e != nil {
		writeError(w, e)
		return
	}
	var req struct {
		SampleID           string  `json:"sampleId"`
		AssignmentID       string  `json:"assignmentId"`
		ContainerType      string  `json:"containerType"`
		ObservedTemperatureC float64 `json:"observedTemperatureC"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeError(w, errInvalidJSON)
		return
	}
	var tmin, tmax float64
	var container string
	err := a.pg.QueryRow(r.Context(), `SELECT temperature_min_c, temperature_max_c, container_type FROM samples WHERE sample_id::text=$1`, req.SampleID).Scan(&tmin, &tmax, &container)
	if err != nil {
		writeError(w, errNotFound)
		return
	}
	compliant := req.ObservedTemperatureC >= tmin && req.ObservedTemperatureC <= tmax
	cid := uuidStr()
	_, _ = a.pg.Exec(r.Context(), `INSERT INTO checkpoints (checkpoint_id, sample_id, assignment_id, container_type, observed_temperature_c, compliant, recorded_at) VALUES ($1,$2,$3,$4,$5,$6,now())`,
		cid, req.SampleID, nilIfEmpty(req.AssignmentID), req.ContainerType, req.ObservedTemperatureC, compliant)
	if !compliant {
		_, _ = a.pg.Exec(r.Context(), `UPDATE samples SET exception=$1 WHERE sample_id::text=$2`, toJSONB(map[string]any{"reason": "temperature_out_of_range", "category": "handling", "observedTemperatureC": req.ObservedTemperatureC}), req.SampleID)
		_, _ = a.pg.Exec(r.Context(), `INSERT INTO exceptions (exception_id, sample_id, reason, category, observed_at) VALUES ($1,$2,'temperature_out_of_range','handling',now())`, uuidStr(), req.SampleID)
		a.emitRealtime(r.Context(), "sample.exception", "sample", req.SampleID, map[string]any{"reason": "temperature_out_of_range"})
	}
	a.audit(r.Context(), u, "record_handling_checkpoint", "sample", req.SampleID, true, map[string]any{"compliant": compliant})
	writeData(w, 201, map[string]any{
		"checkpointId":         cid,
		"sampleId":             req.SampleID,
		"compliant":            compliant,
		"observedTemperatureC": req.ObservedTemperatureC,
	})
}

// handleConfirmLaboratoryReceipt implements POST /api/confirm-laboratory-receipt (laboratory_team).
func (a *App) handleConfirmLaboratoryReceipt(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
		return
	}
	u := currentUser(r)
	if e := requireRole(u, "laboratory_team"); e != nil {
		writeError(w, e)
		return
	}
	var req struct {
		AssignmentID string `json:"assignmentId"`
		SampleID     string `json:"sampleId"`
		ReceivedAt   string `json:"receivedAt"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeError(w, errInvalidJSON)
		return
	}
	var labID *string
	if req.AssignmentID != "" {
		ar, e := loadAssignment(r.Context(), a.pg, req.AssignmentID)
		if e != nil {
			writeError(w, e)
			return
		}
		if ar.WorkerID == nil || *ar.WorkerID != u.UserID {
			writeError(w, errForbidden)
			return
		}
		labID = ar.LabID
		_, _ = a.pg.Exec(r.Context(), `UPDATE assignments SET status='completed' WHERE assignment_id::text=$1`, req.AssignmentID)
	} else {
		var aLoc *string
		_ = a.pg.QueryRow(r.Context(), `SELECT assigned_location_id::text FROM users WHERE user_id::text=$1`, u.UserID).Scan(&aLoc)
		labID = aLoc
	}
	_, err := a.pg.Exec(r.Context(), `UPDATE samples SET status='received', received_laboratory_id=$1, current_holder_id=NULL WHERE sample_id::text=$2`, labID, req.SampleID)
	if err != nil {
		writeError(w, errConflict)
		return
	}
	// Complete the journey.
	_, _ = a.pg.Exec(r.Context(), `UPDATE journeys SET status='completed' WHERE journey_id=(SELECT active_journey_id FROM samples WHERE sample_id::text=$1)`, req.SampleID)
	a.audit(r.Context(), u, "confirm_laboratory_receipt", "sample", req.SampleID, true, map[string]any{"laboratoryId": strPtr(labID)})
	a.emitRealtime(r.Context(), "sample.received", "sample", req.SampleID, map[string]any{"laboratoryId": strPtr(labID)})
	writeData(w, 201, map[string]any{
		"sampleId":      req.SampleID,
		"status":        "received",
		"laboratoryId":  strPtr(labID),
		"receivedAt":    nowRFC(),
	})
}

