// pgxRows aliases pgx.Rows for handler scan helpers.
type pgxRows = pgx.Rows

// jsonRaw returns a json.RawMessage for embedding a raw JSON column value.
func jsonRaw(b []byte) json.RawMessage {
	if len(b) == 0 {
		return nil
	}
	return json.RawMessage(b)
