// canViewSample authorizes a user to view a sample's lifecycle/details.
func (a *App) canViewSample(ctx context.Context, u *AuthUser, sampleID string) *apiError {
	if u == nil {
		return errUnauthorized
	}
	if u.ActiveRole == "administrator" || u.ActiveRole == "dispatcher" {
		return nil
	}
	if u.ActiveRole == "requester" {
		var owner string
		_ = a.pg.QueryRow(ctx, `SELECT requester_id::text FROM samples WHERE sample_id::text=$1`, sampleID).Scan(&owner)
		if owner != u.UserID {
			return errForbidden
		}
		return nil
	}
	// Workers may view samples they are responsible for (current holder or assigned).
	var holder, assignWorker string
	_ = a.pg.QueryRow(ctx, `SELECT COALESCE(current_holder_id::text,''), COALESCE((SELECT a.worker_id::text FROM assignments a WHERE a.sample_id::text=s.sample_id::text AND a.worker_id::text=$2 ORDER BY a.created_at DESC LIMIT 1),'') FROM samples s WHERE s.sample_id::text=$1`, sampleID, u.UserID).
		Scan(&holder, &assignWorker)
	if holder != u.UserID && assignWorker != u.UserID {
		return errForbidden
	}
	return nil
}

// sampleLifecycle builds the ordered status timeline for a sample.
func (a *App) sampleLifecycle(ctx context.Context, sampleID string) map[string]any {
	// Current sample state.
	var status, sealed string
	var holder *string
	var lat, lng *float64
	var locAt *string
	var exc []byte
	var stName, origin string
	_ = a.pg.QueryRow(ctx, `SELECT s.status, CASE WHEN s.sealed THEN 'sealed' ELSE 'not_sealed' END, s.current_holder_id::text, s.latest_latitude, s.latest_longitude, s.location_recorded_at::text, s.exception, st.name, s.origin_type
		FROM samples s JOIN sample_types st ON st.sample_type_id=s.sample_type_id WHERE s.sample_id::text=$1`, sampleID).
		Scan(&status, &sealed, &holder, &lat, &lng, &locAt, &exc, &stName, &origin)

	timeline := []map[string]any{}
	// Audit records describe the chronological history.
	rows, _ := a.pg.Query(ctx, `SELECT occurred_at::text, action, outcome, COALESCE(changes,'\{\}')::jsonb FROM audit_log WHERE entity_type='sample' AND entity_id::text=$1 ORDER BY occurred_at ASC`, sampleID)
	if rows != nil {
		for rows.Next() {
			var at, action, outcome string
			var changes []byte
			_ = rows.Scan(&at, &action, &outcome, &changes)
			entry := map[string]any{
				"at":     at,
				"action": action,
				"outcome": outcome,
			}
			if len(changes) > 0 && string(changes) != "null" {
				entry["changes"] = jsonRaw(changes)
			}
			timeline = append(timeline, entry)
		}
		rows.Close()
	}

	loc := map[string]any{}
	if lat != nil && lng != nil {
		loc["latitude"] = *lat
		loc["longitude"] = *lng
		loc["recordedAt"] = strPtr(locAt)
		stale := false
		if locAt != nil && *locAt != "" {
			// stale if older than 30 minutes
			if t, err := parseRFC3339(*locAt); err == nil {
				stale = timeSince(t).Minutes() > 30
			}
		}
		loc["stale"] = stale
	}

	out := map[string]any{
		"sampleId":    sampleID,
		"sampleType":  stName,
		"status":      status,
		"sealed":      sealed == "sealed",
		"originType":  origin,
		"currentHolderId": strPtr(holder),
		"location":     loc,
		"timeline":     timeline,
	}
	if len(exc) > 0 && string(exc) != "null" {
		out["exception"] = jsonRaw(exc)
	}
	return out
}","path":"/workspace/backend/helpers_misc.go"}

