{"command":"cd /workspace && python3 -c "
import json
c = json.load(open('contracts/openapi.contract.json'))
def ref(n): return n.split('/')[-1]
def schema_ref(d):
    if '\$ref' in d: return ref(d['\$ref'])
    return None
out=[]
for p, item in c['paths'].items():
    for m, op in item.items():
        if m not in ('get','post','put','patch','delete'): continue
        line = f'=== {m.upper()} {p}  opId={op.get(\"operationId\")} ==='
        out.append(line)
        # request body
        rb = op.get('requestBody',{})
        if rb:
            content = rb.get('content',{})
            app = content.get('application/json',{})
            sch = app.get('schema',{})
            if '\$ref' in sch:
                out.append(f'  REQ BODY -> {ref(sch[\"\$ref\"])}')
            else:
                props = sch.get('properties',{})
                reqd = sch.get('required',[])
                for prop, d in props.items():
                    t = d.get('type') or (ref(d['\$ref']) if '\$ref' in d else '?')
                    if d.get('type')=='array' and 'items' in d:
                        it=d['items']; t='array['+(ref(it['\$ref']) if '\$ref' in it else it.get('type','?'))+']'
                    out.append(f'    {prop:26} {t:14} {\"REQ\" if prop in reqd else \"\"}')
        # params
        for prm in op.get('parameters',[]):
            out.append(f'  PARAM {prm.get(\"name\")} ({prm.get(\"in\")}) {\"REQ\" if prm.get(\"required\") else \"\"} schema={prm.get(\"schema\",{}).get(\"type\")}')
        # responses
        for code, resp in op.get('responses',{}).items():
            content = resp.get('content',{})
            app = content.get('application/json',{})
            sch = app.get('schema',{})
            if '\$ref' in sch:
                out.append(f'  RESP {code} -> {ref(sch[\"\$ref\"])}')
            elif sch.get('type')=='object' and 'properties' in sch:
                out.append(f'  RESP {code} object:')
                for prop, d in sch['properties'].items():
                    t = d.get('type') or (ref(d['\$ref']) if '\$ref' in d else '?')
                    if d.get('type')=='array' and 'items' in d:
                        it=d['items']; t='array['+(ref(it['\$ref']) if '\$ref' in it else it.get('type','?'))+']'
                    out.append(f'      {prop:24} {t}')
            else:
                out.append(f'  RESP {code} {sch}')
open('/tmp/ops.txt','w').write('\n'.join(out))
print('\n'.join(out))
" 2>&1 | head -400"}

