{"command":"str_replace","new_str":"// withIdempotency wraps a handler that needs idempotency_key, returning stored response on repeat.
func (a *App) withIdempotency(r *http.Request, op, key string, fn func() (any, int, *apiError)) (any, int, *apiError) {
	if key == "" {
		return nil, 400, errCode(400, "idempotency_required", "idempotencyKey required")
	}
	// check existing
	var respBytes []byte
	var sc int
	err := a.pg.QueryRow(r.Context(), `SELECT response, status_code FROM idempotency_keys WHERE key=$1 AND operation=$2`, key, op).Scan(&respBytes, &sc)
	if err == nil {
		// replay
		var data any
		_ = json.Unmarshal(respBytes, &data)
		return data, sc, nil
	}
	data, status, e := fn()
	if e != nil {
		return nil, e.status, e
	}
	b, _ := json.Marshal(data)
	_, _ = a.pg.Exec(r.Context(), `INSERT INTO idempotency_keys (key, operation, response, status_code) VALUES ($1,$2,$3,$4) ON CONFLICT DO NOTHING`, key, op, b, status)
	return data, status, nil
}

// coordIn is the contract coordinate request object.
type coordIn struct {
	Latitude  float64 `json:"latitude"`
	Longitude float64 `json:"longitude"`
}

// strOmitEmpty returns the dereferenced string, or "" if nil (used for optional string fields).
func strOmitEmpty(s *string) string {
	if s == nil {
		return ""
	}
	return *s
}

// coordOut builds a coordinate output object, or nil if both zero.
func coordOut(lat, lng *float64) map[string]any {
	if lat == nil || lng == nil {
		return nil
	}
	return map[string]any{"latitude": *lat, "longitude": *lng}
}

// locationStale returns true if the recorded-at timestamp is older than 30 minutes.
func locationStale(locAt string) bool {
	if locAt == "" {
		return false
	}
	if t, err := time.Parse(time.RFC3339Nano, locAt); err == nil {
		return time.Since(t).Minutes() > 30
	}
	if t, err := time.Parse(time.RFC3339, locAt); err == nil {
		return time.Since(t).Minutes() > 30
	}
	return false
