        s=resolve(rb['\$ref']) if '\$ref' in rb else rb
        props=s.get('properties',{})
        print('===',op.get('operationId'),path)
        for k,v in props.items():
            t=v.get('type') or ('$ref '+v.get('\$ref','')) or v.get('oneOf','')
            print('   ',k,':',t, 'REQUIRED' if k in s.get('required',[]) else '')
""}

