// handleUpdateLocation implements POST /api/update-location (admin only).
func (a *App) handleUpdateLocation(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
		return
	}
	u := currentUser(r)
	if e := requireRole(u, "administrator"); e != nil {
		writeError(w, e)
		return
	}
	var req struct {
		LocationID string    `json:"locationId"`
		Name       string    `json:"name"`
		Coordinate *coordIn  `json:"coordinate"`
		Functions  []string  `json:"functions"`
		CoverageKm float64   `json:"coverageKm"`
		HandlingMin int      `json:"handlingMinutes"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeError(w, errInvalidJSON)
		return
	}
	if req.LocationID == "" {
		writeError(w, errNotFound)
		return
	}
	for _, f := range req.Functions {
		if !validLocationFunction(f) {
			writeError(w, errCode(400, "invalid_location_function", "invalid function"))
			return
		}
	}
	if req.CoverageKm < 0 || req.CoverageKm > 5 {
		writeError(w, errCode(400, "invalid_node_coverage", "coverage must be 0..5"))
		return
	}
	if req.HandlingMin < 0 || req.HandlingMin > 1440 {
		writeError(w, errCode(400, "invalid_handling_time", "handling must be 0..1440"))
		return
	}
	fm := funcsFromList(req.Functions)
	args := []any{req.Name, req.CoverageKm, req.HandlingMin, fm["collection_point"], fm["transfer_point"], fm["hub"], fm["laboratory"], req.LocationID, locTypeFromFuncs(fm)}
	sql := `UPDATE locations SET name=$1, coverage_km=$2, handling_minutes=$3,
		fn_collection_point=$4, fn_transfer_point=$5, fn_hub=$6, fn_laboratory=$7, location_type=$9`
	if req.Coordinate != nil {
		sql += `, latitude=$10, longitude=$11`
		args = append(args, req.Coordinate.Latitude, req.Coordinate.Longitude)
	}
	sql += ` WHERE location_id::text=$8`
	ct, err := a.pg.Exec(r.Context(), sql, args...)
	if err != nil || ct.RowsAffected() == 0 {
		writeError(w, errNotFound)
		return
	}
	a.audit(r.Context(), u, "update_location", "location", req.LocationID, true, nil)
