	if _, err := a.pg.Exec(ctx, drop); err != nil {
		return err
	}
	if err := a.Migrate(ctx); err != nil {
		return err
	}
	return nil
}","path":"/workspace/backend/migrate.go"}

{"command":"str_replace","new_str":"// serveFrontend serves the SPA from the frontend/dist directory if present.
// The directory is resolved relative to the working directory, then the
// executable's directory, so serving works regardless of the CWD.
func (a *App) serveFrontend() http.Handler {
	dir := resolveFrontendDir()
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if dir == "" {
			http.NotFound(w, r)
			return
		}
		if r.URL.Path == "/" || strings.HasPrefix(r.URL.Path, "/assets") {
			fp := filepath.Join(dir, r.URL.Path)
			if r.URL.Path == "/" {
				fp = filepath.Join(dir, "index.html")
			}
			if data, err := os.ReadFile(fp); err == nil {
				w.Header().Set("Content-Type", contentTypeFor(fp))
				_, _ = w.Write(data)
				return
			}
		}
		// fallback to index.html for SPA routes
		if data, err := os.ReadFile(filepath.Join(dir, "index.html")); err == nil {
			w.Header().Set("Content-Type", "text/html; charset=utf-8")
			_, _ = w.Write(data)
			return
		}
		http.NotFound(w, r)
	})
}

// resolveFrontendDir finds the frontend/dist directory. It first honors the
// FRONTEND_DIR env var, then tries "frontend/dist" relative to the current
// working directory, then relative to the directory of the running binary.
func resolveFrontendDir() string {
	candidates := []string{}
	if env := os.Getenv("FRONTEND_DIR"); env != "" {
		candidates = append(candidates, env)
	}
	if cwd, err := os.Getwd(); err == nil {
		candidates = append(candidates, filepath.Join(cwd, "frontend", "dist"))
	}
	if exe, err := os.Executable(); err == nil {
		if exeDir, err := filepath.Abs(filepath.Dir(exe)); err == nil {
			candidates = append(candidates,
				filepath.Join(exeDir, "frontend", "dist"),
				filepath.Join(exeDir, "..", "frontend", "dist"),
			)
		}
	}
	for _, c := range candidates {
		if st, err := os.Stat(c); err == nil && st.IsDir() {
			return c
		}
	}
	return ""
}","old_str":"// serveFrontend serves the SPA from the embedded/asset directory if present.
