{"command":"create","file_text":"import type {
  ApiError,
  Bootstrap,
  ServiceabilityResult,
  ServiceabilitySnapshot,
  SampleState,
  SampleLifecycle,
  RoleWork,
  OperationsState,
  JourneyPlan,
  AuditSearchResult,
  UserInfo,
  Role,
} from "./types";

const BASE = "";

let token: string | null = null;

export function getToken(): string | null {
  return token;
}

export function setToken(t: string | null) {
  token = t;
  if (t) localStorage.setItem("labpd_token", t);
  else localStorage.removeItem("labpd_token");
}

export function loadStoredToken() {
  const t = localStorage.getItem("labpd_token");
  if (t) token = t;
}

async function req<T>(
  method: string,
  path: string,
  body?: unknown
): Promise<T> {
  const headers: Record<string, string> = {};
  let url = BASE + path;
  const init: RequestInit = { method, headers };
  if (token) headers["Authorization"] = "Bearer " + token;
  if (body !== undefined) {
    headers["Content-Type"] = "application/json";
    init.body = JSON.stringify(body);
  }
  const res = await fetch(url, init);
  const text = await res.text();
  let data: unknown = null;
  if (text) {
    try {
      data = JSON.parse(text);
    } catch {
      data = text;
    }
  }
  if (!res.ok) {
    const err = (data && typeof data === "object" ? data : { error: String(data) }) as ApiError;
    const e = new Error(err.error || `HTTP ${res.status}`) as Error & {
      code?: string;
      status?: number;
    };
    e.code = err.code;
    e.status = res.status;
    throw e;
  }
  // unwrap { data: ... }
  if (data && typeof data === "object" && "data" in (data as Record<string, unknown>)) {
    return (data as { data: T }).data;
  }
  return data as T;
}

