{"command":"create","file_text":"import { useEffect, useState, useCallback, createContext, useContext } from "react";
import { api, loadStoredToken, setToken, getToken } from "./api";
import type { Bootstrap, Role } from "./types";
import { ROLE_LABELS } from "./util";
import { Login } from "./components/Login";
import { RoleSwitcher } from "./components/RoleSwitcher";
import { Sidebar } from "./components/Sidebar";
import { RequesterView } from "./components/RequesterView";
import { WorkerView } from "./components/WorkerView";
import { MonitorView } from "./components/MonitorView";
import { AdminView } from "./components/AdminView";
import { MapView } from "./components/MapView";
import { SampleDetail } from "./components/SampleDetail";
import { AuditView } from "./components/AuditView";

export interface NavState {
  page: string;
  param?: string;
}

interface Ctx {
  bootstrap: Bootstrap | null;
  reloadBootstrap: () => Promise<void>;
  navigate: (page: string, param?: string) => void;
  nav: NavState;
}

const AppCtx = createContext<Ctx>({} as Ctx);
export const useApp = () => useContext(AppCtx);

export function App() {
  const [bootstrap, setBootstrap] = useState<Bootstrap | null>(null);
  const [bootError, setBootError] = useState<string | null>(null);
  const [authed, setAuthed] = useState(false);
  const [nav, setNav] = useState<NavState>({ page: "home" });
  const [loading, setLoading] = useState(true);

  const reloadBootstrap = useCallback(async () => {
    if (!getToken()) return;
    try {
      const b = await api.bootstrap();
      setBootstrap(b);
      setBootError(null);
    } catch (e) {
      setBootError((e as Error).message);
    }
  }, []);

  useEffect(() => {
    loadStoredToken();
    if (!getToken()) {
      setLoading(false);
      return;
    }
    api
      .bootstrap()
      .then((b) => {
        setBootstrap(b);
        setAuthed(true);
        setLoading(false);
      })
      .catch(() => {
        setToken(null);
        setLoading(false);
      });
  }, []);

  const navigate = useCallback((page: string, param?: string) => {
    setNav({ page, param });
  }, []);

  const onLogin = useCallback(async () => {
    setAuthed(true);
    await reloadBootstrap();
    setNav({ page: "home" });
  }, [reloadBootstrap]);

  if (loading) {
    return <div className="login-wrap"><div className="muted">LoadingÃ¢Â¦</div></div>;
  }

  if (!authed) {
    return <Login onLogin={onLogin} />;
  }

  if (bootError) {
    return (
      <div className="login-wrap">
        <div className="login-card">
          <h1>Session error</h1>
          <p className="error-msg">{bootError}</p>
          <button
            onClick={() => {
              setToken(null);
              setAuthed(false);
              setBootError(null);
            }}
          >
            Sign out
          </button>
        </div>
      </div>
    );
  }

  if (!bootstrap) return <div className="login-wrap"><div className="muted">LoadingÃ¢Â¦</div></div>;

  return (
    <AppCtx.Provider value={{ bootstrap, reloadBootstrap, navigate, nav }}>
      <Shell />
    </AppCtx.Provider>
  );
}

function Shell() {
  const { bootstrap, reloadBootstrap, navigate, nav } = useApp();
  const role = bootstrap!.user.activeRole;

  const pages = availablePages(role);

  const handleNavigate = (page: string) => {
    navigate(page);
  };

  return (
    <div className="app-shell">
      <div className="topbar">
        <span className="brand">ð§¬ Lab Sample Pickup &amp; Delivery</span>
        <span className="badge muted">{ROLE_LABELS[role] || role}</span>
        <RoleSwitcher
          roles={bootstrap!.user.roles}
          activeRole={role}
          onChanged={reloadBootstrap}
        />
        <span className="spacer" />
        <span className="muted small">{bootstrap!.user.username}</span>
        <button
          className="small"
          onClick={() => {
            setToken(null);
            window.location.reload();
          }}
        >
          Sign out
        </button>
      </div>
      <div className="layout">
        <Sidebar pages={pages} current={nav.page} onNavigate={handleNavigate} />
        <div className="main">
          <PageRouter />
        </div>
      </div>
    </div>
  );
}

function availablePages(role: Role): { id: string; label: string }[] {
  const base: { id: string; label: string }[] = [];
  switch (role) {
    case "requester":
      base.push({ id: "home", label: "My Requests" });
      base.push({ id: "new-request", label: "New Request" });
      base.push({ id: "serviceability", label: "Serviceability Check" });
      base.push({ id: "map", label: "Map" });
      break;
    case "collection_professional":
    case "delivery_partner":
    case "node_handler":
    case "laboratory_team":
      base.push({ id: "home", label: "My Work" });
      base.push({ id: "map", label: "Map" });
      break;
    case "dispatcher":
    case "administrator":
      base.push({ id: "home", label: "Monitor Dashboard" });
      base.push({ id: "admin", label: "Admin" });
      base.push({ id: "map", label: "Map" });
      base.push({ id: "audit", label: "Audit Trail" });
      break;
  }
  return base;
}

function PageRouter() {
  const { nav, bootstrap } = useApp();
  const role = bootstrap!.user.activeRole;

  if (nav.page === "sample") {
    return <SampleDetail sampleId={nav.param!} />;
  }
  if (nav.page === "map") {
    return <MapView />;
  }
  if (nav.page === "audit") {
    return <AuditView />;
  }
  if (nav.page === "admin") {
    return <AdminView />;
  }
  if (role === "requester") {
    return <RequesterView page={nav.page} />;
  }
  if (role === "dispatcher" || role === "administrator") {
    return <MonitorView />;
  }
  return <WorkerView />;
}","path":"/workspace/frontend/src/App.tsx"}

{"command":"create","file_text":"import { useState } from "react";
import { api, setToken } from "../api";

export function Login({ onLogin }: { onLogin: () => void }) {
  const [username, setUsername] = useState("admin");
  const [password, setPassword] = useState("admin123");
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const submit = async (e: React.FormEvent) => {
    e.preventDefault();
    setBusy(true);
    setError(null);
    try {
      const res = await api.authenticate(username, password);
      setToken(res.sessionToken);
      onLogin();
    } catch (e) {
      setError((e as Error).message || "Authentication failed");
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="login-wrap">
      <form className="login-card" onSubmit={submit}>
        <h1>Lab Sample Pickup</h1>
        <p>Sign in to manage sample collection and delivery.</p>
        <div className="form-row">
          <label>Username</label>
          <input value={username} onChange={(e) => setUsername(e.target.value)} autoFocus />
        </div>
        <div className="form-row">
          <label>Password</label>
          <input
