{"command":"create","file_text":"import { useState } from "react";
import { api } from "../api";
import type { Role } from "../types";
import { ROLE_LABELS } from "../util";

export function RoleSwitcher({
  roles,
  activeRole,
  onChanged,
}: {
  roles: Role[];
  activeRole: Role;
  onChanged: () => void;
}) {
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);

  const change = async (e: React.ChangeEvent<HTMLSelectElement>) => {
    const role = e.target.value as Role;
    if (role === activeRole) return;
    setBusy(true);
    setErr(null);
    try {
      await api.selectRole(role);
      onChanged();
    } catch (e) {
      setErr((e as Error).message);
    } finally {
      setBusy(false);
    }
  };

  return (
    <div>
      <select
        className="role-select"
        value={activeRole}
        onChange={change}
        disabled={busy || roles.length <= 1}
        title="Switch active role"
      >
        {roles.map((r) => (
          <option key={r} value={r}>
            {ROLE_LABELS[r] || r}
          </option>
        ))}
      </select>
      {err && <span className="error-msg" style={{ marginLeft: 8 }}>{err}</span>}
    </div>
  );
}","path":"/workspace/frontend/src/components/RoleSwitcher.tsx"}

