function UsersTab() {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [fullName, setFullName] = useState("");
  const [email, setEmail] = useState("");
  const [roles, setRoles] = useState<string[]>(["requester"]);
  const [result, setResult] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [userId, setUserId] = useState("");
  const [userInfo, setUserInfo] = useState<any>(null);
  const [busy, setBusy] = useState(false);

  const allRoles = ["administrator", "dispatcher", "requester", "collection_professional", "delivery_partner", "node_handler", "laboratory_team"];

  const create = async () => {
    setBusy(true); setError(null); setResult(null);
    try {
      const r = await api.createUser({ username, password, fullName, email, roles });
      setResult(`Created user ${username}.`);
      setUsername(""); setPassword(""); setFullName(""); setEmail("");
    } catch (e) { setError((e as Error).message); }
    finally { setBusy(false); }
  };

  const lookup = async () => {
    setError(null); setUserInfo(null);
    try { const u = await api.readUser(userId); setUserInfo(u); } catch (e) { setError((e as Error).message); }
  };

  const toggleRole = (r: string) => {
    setRoles((prev) => prev.includes(r) ? prev.filter((x) => x !== r) : [...prev, r]);
  };

  return (
    <div className="grid grid-2">
      <div className="panel">
