              <tr><th>Assigned location</th><td>{userInfo.assignedLocationId || "ÃÃÃÃÂ¢ÃÃ"}</td></tr>
              <tr><th>Active</th><td>{String(userInfo.active)}</td></tr>
            </tbody></table>
          </div>
        )}
      </div>
    </div>
  );
}

