{"command":"create","file_text":"import { useState } from "react";
import { api } from "../api";
import type { AuditSearchResult } from "../types";
import { fmtTime } from "../util";

export function AuditView() {
  const [query, setQuery] = useState("");
  const [entityType, setEntityType] = useState("");
  const [entityId, setEntityId] = useState("");
  const [action, setAction] = useState("");
  const [actor, setActor] = useState("");
  const [from, setFrom] = useState("");
  const [until, setUntil] = useState("");
  const [result, setResult] = useState<AuditSearchResult | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const search = async () => {
    setLoading(true); setError(null);
    try {
      const body: Record<string, unknown> = { limit: 100, order: "desc" };
      if (query) body.query = query;
      if (entityType) body.entityType = entityType;
      if (entityId) body.entityId = entityId;
      if (action) body.action = action;
      if (actor) body.actorId = actor;
      if (from) body.from = new Date(from).toISOString();
      if (until) body.until = new Date(until).toISOString();
      const r = await api.searchAudit(body);
      setResult(r);
    } catch (e) { setError((e as Error).message); }
    finally { setLoading(false); }
  };

  return (
    <div>
      <h2>Audit Trail</h2>
      <div className="panel">
        <div className="grid grid-3">
          <div className="form-row"><label>Query</label><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="free text" /></div>
          <div className="form-row"><label>Entity type</label>
            <select value={entityType} onChange={(e) => setEntityType(e.target.value)}>
              <option value="">any</option>
              <option>sample</option><option>request</option><option>journey</option>
              <option>assignment</option><option>handoff</option><option>location</option>
              <option>connection</option><option>capacity</option><option>user</option>
            </select>
          </div>
          <div className="form-row"><label>Entity ID</label><input value={entityId} onChange={(e) => setEntityId(e.target.value)} /></div>
          <div className="form-row"><label>Action</label><input value={action} onChange={(e) => setAction(e.target.value)} placeholder="e.g. collect_and_seal" /></div>
          <div className="form-row"><label>Actor ID</label><input value={actor} onChange={(e) => setActor(e.target.value)} /></div>
          <div className="form-row"><label>From</label><input type="datetime-local" value={from} onChange={(e) => setFrom(e.target.value)} /></div>
          <div className="form-row"><label>Until</label><input type="datetime-local" value={until} onChange={(e) => setUntil(e.target.value)} /></div>
        </div>
        <button className="primary" onClick={search} disabled={loading} style={{ marginTop: 8 }}>
          {loading ? "SearchingÃÃÃÃÂ¢ÃÂ¦" : "Search audit trail"}
        </button>
        {error && <div className="error-msg">{error}</div>}
      </div>

      {result && (
        <div className="panel">
          <h3>{result.total} results (showing {result.returned})</h3>
          {result.entries.length === 0 ? <span className="muted">No matching audit records.</span> : (
            <table>
              <thead><tr><th>Time</th><th>Actor</th><th>Role</th><th>Action</th><th>Entity</th><th>Result</th></tr></thead>
              <tbody>
                {result.entries.map((e) => (
                  <tr key={e.auditId}>
                    <td>{fmtTime(e.occurredAt)}</td>
                    <td>{e.actorId.slice(0, 8)}</td>
                    <td>{e.role || e.actorRole}</td>
                    <td><strong>{e.action}</strong></td>
                    <td>{e.entityType}:{e.entityId.slice(0, 8)}</td>
                    <td>{e.success ? <span className="badge ok">ok</span> : <span className="badge danger">failed</span>}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      )}
    </div>
  );
}","path":"/workspace/frontend/src/components/AuditView.tsx"}

{"command":"create","file_text":"import { useEffect, useRef, useState } from "react";
import maplibregl from "maplibre-gl";
import { Protocol } from "pmtiles";
import "maplibre-gl/dist/maplibre-gl.css";
import { api } from "../api";
import type { OperationsState } from "../types";

const CENTER: [number, number] = [77.5946, 12.9716];

export function MapView() {
  const containerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<maplibregl.Map | null>(null);
  const [state, setState] = useState<OperationsState | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    api.readOperationsState().then(setState).catch((e) => setError((e as Error).message));
  }, []);

  useEffect(() => {
    if (!containerRef.current || mapRef.current) return;

    const protocol = new Protocol();
    maplibregl.addProtocol("pmtiles", protocol.tile);

    const map = new maplibregl.Map({
      container: containerRef.current,
      style: "/map-assets/style.json",
      center: CENTER,
      zoom: 10,
    });
    mapRef.current = map;

    map.addControl(new maplibregl.NavigationControl(), "top-right");

    map.on("load", () => {
      addOverlays(map);
    });

    return () => {
      map.remove();
      mapRef.current = null;
    };
  }, []);

  useEffect(() => {
    const map = mapRef.current;
    if (!map || !state || !map.loaded()) return;
    updateOverlays(map, state);
  }, [state]);

  const addOverlays = (map: maplibregl.Map) => {
    map.addSource("samples", { type: "geojson", data: { type: "FeatureCollection", features: [] } });
    map.addSource("workers", { type: "geojson", data: { type: "FeatureCollection", features: [] } });
    map.addSource("nodes", { type: "geojson", data: { type: "FeatureCollection", features: [] } });

    map.addLayer({
      id: "nodes",
      type: "circle",
      source: "nodes",
      paint: { "circle-radius": 7, "circle-color": "#4f9eff", "circle-stroke-color": "#fff", "circle-stroke-width": 1.5 },
    });

    map.addLayer({
      id: "samples",
      type: "circle",
      source: "samples",
      paint: {
        "circle-radius": 6,
        "circle-color": ["case", ["get", "exception"], "#ff5a6a", "#2bd4a0"],
        "circle-stroke-color": "#fff", "circle-stroke-width": 1.5,
      },
    });

    map.addLayer({
      id: "workers",
      type: "circle",
      source: "workers",
      paint: { "circle-radius": 5, "circle-color": "#ffb84d", "circle-stroke-color": "#fff", "circle-stroke-width": 1 },
    });

    const popup = new maplibregl.Popup({ offset: 15 });
    for (const layerId of ["nodes", "samples", "workers"]) {
      map.on("click", layerId, (e) => {
        const f = e.features?.[0];
        if (!f) return;
        const html = (f.properties?.html as string) || f.properties?.title || "";
        popup.setLngLat(e.lngLat).setHTML(html).addTo(map);
      });
      map.on("mouseenter", layerId, () => (map.getCanvas().style.cursor = "pointer"));
      map.on("mouseleave", layerId, () => (map.getCanvas().style.cursor = ""));
    }
  };

  const updateOverlays = (map: maplibregl.Map, st: OperationsState) => {
    const sampleFeats = ((st.samples || []) as any[])
