{"command":"str_replace","new_str":"// handleDeclineAssignment implements POST /api/decline-assignment.
func (a *App) handleDeclineAssignment(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
		return
	}
	u := currentUser(r)
	if e := requireRole(u, workerRoles()...); e != nil {
		writeError(w, e)
		return
	}
	var req struct {
		AssignmentID  string `json:"assignmentId"`
		Reason        string `json:"reason"`
		DeclinedAt    string `json:"declinedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeError(w, errInvalidJSON)
		return
	}
	ar, e := loadAssignment(r.Context(), a.pg, req.AssignmentID)
	if e != nil {
		writeError(w, e)
		return
	}
	if ar.WorkerID == nil || *ar.WorkerID != u.UserID {
		writeError(w, errCode(403, "not_assigned", "assignment not offered to you"))
		return
	}
	_, _ = a.pg.Exec(r.Context(), `INSERT INTO assignment_declines (assignment_id, worker_id) VALUES ($1,$2) ON CONFLICT DO NOTHING`, req.AssignmentID, u.UserID)
	// Re-offer to next eligible worker.
	nextWorker := a.reofferAssignment(r.Context(), ar, u.UserID)
	declinedAt := nowRFC()
	if req.DeclinedAt != "" {
		if t, perr := parseTime(req.DeclinedAt, "invalid_time"); perr == nil {
			declinedAt = rfc(t)
		}
	}
	a.audit(r.Context(), u, "decline_assignment", "assignment", req.AssignmentID, true, map[string]any{"reason": req.Reason})
	out := map[string]any{
		"assignmentId": req.AssignmentID,
		"status":       "offered",
		"declinedBy":   u.UserID,
		"declinedAt":   declinedAt,
	}
	if nextWorker != "" {
		out["reofferedTo"] = nextWorker
